SELECT 
  FROM place p
 WHERE p.place_id = #{placeId}

SELECT pc.place_content_id AS placeContentId, pc.difficulty AS difficulty, pc.language AS language, pc.description AS description, pc.place_id AS placeId FROM place_content pc WHERE pc.place_id IN
#{id}
ORDER BY pc.place_id, pc.difficulty, pc.language, pc.place_content_id

mapper.update:
UPDATE place_content
   SET description = #{description}
 WHERE place_id    = #{placeId}
   AND language    = #{language}
   AND difficulty  = #{difficulty}

UPDATE place
   SET is_active  = FALSE,
       deleted_at = #{deletedAt},
       updated_at = #{deletedAt}
 WHERE place_id   = #{placeId}
   AND is_active  = TRUE

UPDATE place
   SET is_active  = TRUE,
       deleted_at = NULL,
       updated_at = #{updatedAt}
 WHERE place_id   = #{placeId}
   AND is_active  = FALSE
